            "body": "「博山豆腐箱」乃淄博极具代表性的镇桌名馔，源起清末民初传统名作（地方非遗 / 城市名片），深植于鲁菜 · 博山菜的筵席传统之中。庖厨严选豆腐、肉馅为材，恪守「炸酿烧焖」之古法火候，将食材本味与复合汤卤融于一炉。成菜尽显「外酥馅香」的风味层次，入口醇厚馥郁、回味悠长。老饕寻味常赴博山菜馆（博山区）或淄博博山豆腐箱传习酒楼，于堂前热气升腾间一探淄博庖厨的看家功底。这一口传承数代的地道风味，至今仍是远近食客造访淄博必尝的味觉名片。",
