            "body": "「周村古商城传统砂锅煮锅」撑起了淄博人一日三餐的碳水信仰，渊源可溯至清末民初传统名作（地方非遗 / 城市名片），堪称鲁菜 · 博山菜主食谱系的灵魂坐标。店家讲究以博山炸肉丸、五花肉片、老豆腐、手擀面入馔，经「大砂锅高汤滚煮炸丸子五花肉豆腐配周村烧饼同食」悉心烹调，令米麦筋骨饱吸汤卤精华。入口尽展「百年老汤醇厚丸子酥肉猪肝吸汁配手擀面烧饼」之妙，抚慰肚肠且余韵绵密。街头寻味必访周村古商城老字号煮锅店（周村区大街中段）及淄博周村古商城传统砂锅煮锅传习老铺。",
