            "body": "「莜面栲栳栳」撑起了太原人一日三餐的碳水信仰，渊源可溯至清末民初传统名作（地方非遗 / 城市名片），堪称晋菜 · 太原面食主食谱系的灵魂坐标。店家讲究以莜面、羊肉卤入馔，经「蒸制浇卤」悉心烹调，令米麦筋骨饱吸汤卤精华。入口尽展「卷筒蒸莜面浇卤」之妙，抚慰肚肠且余韵绵密。街头寻味必访莜面馆（太原）及太原莜面栲栳栳传习老铺，在一碗热气腾腾的滋味里读懂太原的日常底色。这一口传承数代的地道风味，至今仍是远近食客造访太原必尝的味觉名片。",
